"""Explain guest-host barriers and conditional read ordering with worked examples."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1641': ('작은 교실에 학생이 한 명이어도 바깥 교무실에는 여러 선생님이 일할 수 있어요. 가상 컴퓨터 안의 CPU 수와 그것을 실행하는 바깥 컴퓨터의 작업 수는 달라요.', '가상 머신의 guest·host와 virt 장벽의 필요성을 이해합니다.', 'guest: 가상 CPU 1개 / host: 여러 CPU와 작업을 두 상자로 그리세요. virt_mb는 __smp_mb에 연결된다고 표시하세요.', ['가상 머신은 다른 컴퓨터 안에서 컴퓨터처럼 동작하는 실행 환경이에요. 그 안에서 실행되는 쪽을 guest, 가상 머신을 실행해 주는 바깥 쪽을 host라고 불러요. guest와 host는 서로 데이터를 주고받을 수 있어요.', 'guest에 가상 CPU가 하나만 있어도 host에는 여러 CPU나 동시에 진행하는 작업이 있을 수 있어요. 내 쪽이 혼자 일한다고 상대 쪽까지 혼자라는 뜻은 아니에요. 공유하는 데이터를 어떤 순서로 공개하고 읽는지가 여전히 중요해요.', '공통 헤더의 virt_* 장벽은 guest가 SMP host와 주고받는 경우를 위한 도구예요. SMP는 여러 CPU가 함께 일하는 구성을 뜻해요. 이 virt는 가상 주소를 물리 주소로 바꾸는 함수라는 뜻이 아니에요.', 'virt_mb는 kcsan_mb로 검사 도구에 순서를 알리고 내부 __smp_mb를 호출해요. virt_rmb와 virt_wmb도 각각 읽기·쓰기 알림 뒤 내부 기반 장벽에 연결돼요.', '이 정의는 guest의 CONFIG_SMP가 꺼졌다고 공개 smp_mb의 UP 기본 형태로 갈아타지 않아요. UP의 공개 smp_mb는 기본적으로 컴파일러 장벽일 수 있지만 virt_mb는 __smp_mb라는 내부 연결을 유지해요. 그 내부 장벽의 실제 구현은 CPU별 정의를 따라가야 해요.', '사용할 때는 어떤 공유 메모리에서 누구와 어떤 표시를 주고받는지 먼저 정해야 해요. virt라는 이름만 붙이면 모든 통신 규칙이나 데이터 수명이 자동으로 해결되지는 않아요. 원문의 연결 확인과 실제 가상 머신의 동작 시험도 서로 다른 확인이에요.'], [('가상 CPU 하나인 guest에서 virt_mb는 공개 smp_mb의 UP 기본 형태를 그대로 쓰나요?', ['네. guest CPU가 하나면 host와의 순서도 모두 없애요', '아니요. 내부 __smp_mb로 연결해요'], '정답은 두 번째예요. 원문은 virt_mb에서 검사 알림 뒤 __smp_mb를 호출해요. guest에 CPU가 하나라는 이유로 host와의 동시 작업까지 사라지지는 않아요.'), ('guest의 가상 CPU가 하나이면 host의 모든 작업도 하나만 실행되나요?', ['아니요. guest와 host의 구성을 따로 봐야 해요', '네. host의 모든 실행 흐름도 하나로 제한돼요'], '정답은 첫 번째예요. 가상 머신 안에 보이는 CPU 수와 바깥 host의 CPU·작업 수는 달라요. 공유 데이터의 상대가 누구인지 따져서 순서 규칙을 지켜야 해요.')]), 'os1642': ('안내 창구가 부탁을 받아 실제 담당자에게 넘기는 모습을 생각해 보세요. 겉의 함수 이름에서 어느 내부 도구로 이어지는지 따라가면 동작을 이해하기 쉬워요.', 'virt 저장·읽기 도우미의 연결과 사용 조건을 이해합니다.', 'virt_store_release → kcsan_release → __smp_store_release, virt_load_acquire → __smp_load_acquire를 두 줄로 그리세요.', ['wrapper는 다른 기능을 감싸서 연결하는 작은 코드예요. 여기의 virt 도우미는 가상 머신 guest와 host 사이에서 필요한 메모리 순서를 다뤄요. 제목의 virtual이라는 말을 페이지 테이블을 만드는 기능으로 읽지 마세요.', 'virt_store_mb(var, value)는 먼저 kcsan_mb로 알리고 __smp_store_mb를 호출해요. var는 저장할 자리, value는 넣을 값이에요. 공통 내부 구현에서는 저장을 하고 그 뒤에 기반 장벽을 두는 흐름이에요.', 'virt_store_release(p, v)는 kcsan_release로 알린 뒤 __smp_store_release(p, v)를 호출해요. p는 저장할 칸의 주소이고 v는 새 값이에요. release는 앞서 준비한 접근과 공개 저장의 순서를 연결하는 데 쓰여요.', 'virt_load_acquire(p)는 __smp_load_acquire(p)로 직접 이어져요. 이 wrapper 본문에는 별도의 kcsan_rmb 호출을 덧붙이지 않아요. acquire는 읽은 뒤의 접근에 대한 순서 규칙을 제공하며 결과 값은 기반 읽기에서 와요.', '예를 들어 공유 데이터 준비 뒤 표시를 release로 쓰고, 받는 쪽이 올바른 acquire로 그 공개를 관찰한 후 내용을 사용하도록 규칙을 정할 수 있어요. 어느 쪽이 쓰는지, 어느 표시를 관찰하는지, 그 데이터가 언제까지 유효한지도 함께 정해야 해요.', 'guest가 UP인 경우에도 이 virt 도우미들은 내부 __smp 계열 연결을 유지해요. 공개 smp 도우미의 UP 기본 경로와 코드가 같다고 가정하면 안 돼요. before·after_atomic 도우미도 내부 기반 순서 보강으로 연결되고, 실제 CPU별 동작은 그 정의에서 확인해요.'], [('virt_load_acquire는 어디로 연결되나요?', ['UP이면 항상 아무 조건 없는 일반 대입으로 바뀌어요', '__smp_load_acquire로 연결돼요'], '정답은 두 번째예요. 정의의 오른쪽이 __smp_load_acquire(p)예요. 공개 smp의 UP 기본 분기를 virt에도 그대로 적용해 추측하면 안 돼요.'), ('virt_store_release는 내부 저장 도구 앞에 어떤 검사 알림을 호출하나요?', ['kcsan_release예요', '항상 kcsan_rmb만 호출해요'], '정답은 첫 번째예요. 원문은 kcsan_release(); __smp_store_release(p, v); 순서예요. 읽기 장벽 알림인 kcsan_rmb와 release 공개 알림은 서로 다른 이름과 역할이에요.')]), 'os1643': ('전광판 숫자를 보고 아직 아니면 잠깐 반복 대기 동작을 한 뒤 다시 확인해요. 확인 횟수와 대기 동작 횟수는 같지 않을 수 있어요.', '조건 읽기의 VAL·반복 횟수·반환값을 직접 계산합니다.', '처음 값은 0이고 세 번째 cpu_relax 때 3이 된다고 가정하세요. 읽기1:0 → 대기1 → 읽기2:0 → 대기2 → 읽기3:0 → 대기3 → 읽기4:3을 적으세요.', ['smp_cond_load_relaxed는 지정한 주소의 값을 읽어 조건이 맞을 때까지 반복해요. 일반적인 고정 타입 포인터 식은 처음 __PTR에 보관해서 사용해요. 포인터는 읽을 칸의 주소이고 그 칸에 들어 있는 숫자와는 달라요.', '반복문은 READ_ONCE로 숫자를 읽어 VAL이라는 임시 칸에 넣어요. 조건식 VAL == 3은 방금 읽은 숫자가 3과 같은지 묻는 뜻이에요. ==는 비교이고 값을 넣는 =와 달라요.', '조건이 참이면 break로 반복을 끝내요. 거짓이면 cpu_relax를 거친 뒤 다음 반복에서 다시 읽어요. cpu_relax는 반복 대기에 쓰는 도구이며 반드시 잠들거나 정해진 초를 기다린다는 뜻은 아니에요.', '연습에서는 처음 숫자를 0으로 두고 세 번째 cpu_relax가 끝날 때 3으로 바뀐다고 가정해요. 첫째·둘째·셋째 읽기에서는 0이어서 계속해요. 셋째 대기 뒤 넷째 읽기에서 3을 확인하므로 읽기는 4번, 대기는 3번이에요.', '반복을 끝낸 뒤에는 마지막 VAL을 돌려줘요. 이 예시의 결과는 읽기 횟수 4도, 참을 뜻하는 1도 아닌 관찰값 3이에요. 처음부터 3이었다면 읽기는 1번이고 cpu_relax는 0번이에요.', '세 번째 대기에 값이 바뀐다는 것은 계산 연습의 가정이에요. 실제로 누가 언제 바꾸는지는 바깥 코드에 달려 있어요. 이 매크로에는 시간 초과인 timeout 검사나 기다리는 작업 목록 등록이 없어서 조건이 계속 거짓이면 반복이 끝나지 않을 수 있어요.'], [('처음 값은 0이고 세 번째 cpu_relax가 끝날 때 3이 돼요. VAL == 3을 처음 확인할 때까지 몇 번 읽나요?', ['1번 읽어요', '4번 읽어요'], '정답은 두 번째예요. 읽기1 뒤 대기1, 읽기2 뒤 대기2, 읽기3 뒤 대기3을 거쳐 값이 바뀌어요. 그 다음 읽기4에서 3을 확인해요. 대기 횟수 3과 읽기 횟수 4를 구별하세요.'), ('조건이 계속 거짓이면 이 매크로가 일정 시간 뒤 자동으로 끝내나요?', ['아니요. 이 정의에는 timeout 검사가 없어요', '네. READ_ONCE가 시간이 지나면 자동 종료해요'], '정답은 첫 번째예요. READ_ONCE는 값을 읽는 도구이지 제한 시간을 재는 타이머가 아니에요. 조건을 바꿀 실행 흐름이 진행할 수 있는지도 확인해야 해요.')]), 'os1644': ('신호를 확인해야 다음 행동을 한다는 규칙이 있어도, 컴퓨터가 다른 읽기까지 원하는 순서로 처리한다고 바로 결론 낼 수는 없어요. 필요한 순서 약속을 더해야 해요.', '조건 의존성과 읽기 순서 보강의 차이를 이해합니다.', '조건에 쓰인 읽기 → 뒤의 쓰기와 조건에 쓰인 읽기 → 뒤의 읽기를 두 줄로 그리세요. 둘째의 보강에 RMB가 쓰인다고 적으세요.', ['control dependency는 읽은 값에 따라 다음 동작을 할지 결정하는 관계예요. 예를 들어 준비 표시의 값에 따라 기다림을 끝내는 흐름이 있어요. dependency는 이런 의존 관계를 뜻해요.', 'LOAD는 메모리에서 읽기, STORE는 메모리에 쓰기예요. 이 헤더 주석은 올바른 조건 의존성의 LOAD → STORE 순서와 추가 RMB의 LOAD → LOAD 순서를 합쳐 acquire 범위를 구성한다고 설명해요.', 'RMB는 읽기 메모리 장벽이에요. 앞의 읽기와 뒤의 읽기에 필요한 순서를 보강해요. 단순히 if 문이 있다는 이유만으로 이 읽기 순서까지 모두 생긴다고 외우면 안 돼요.', 'CPU는 속도를 높이려고 뒤에서 필요할 것 같은 읽기를 미리 진행할 수 있어요. 이런 미리 읽기를 load speculation이라고 불러요. 컴파일러도 코드를 변환할 수 있으므로 소스에 조건문 하나를 적었다는 사실만으로 모든 순서 보장을 대신할 수는 없어요.', '공통 smp_acquire__after_ctrl_dep의 기본값은 smp_rmb예요. 조건을 만족할 때까지 relaxed로 읽은 다음 이 보강을 수행하고 관찰한 값을 반환하는 것이 조건부 acquire의 흐름이에요.', 'CPU별로 필요한 구현은 달라요. 원문은 미리 읽기를 하지 않는 아키텍처에서는 이 보강을 컴파일러 장벽으로 구현할 수 있다고 설명해요. 그것은 해당 CPU의 조건에 맞춘 선택이지 누구나 임의의 if나 nop으로 acquire를 바꿔도 된다는 허락이 아니에요.'], [('공통 smp_acquire__after_ctrl_dep의 기본 연결은 무엇인가요?', ['항상 nop 한 번이에요', 'smp_rmb예요'], '정답은 두 번째예요. 기본 정의는 smp_rmb로 이어져 필요한 읽기 순서를 보강해요. nop은 그 순서 약속을 대신하는 기본값이 아니에요.'), ('아무 if 문이나 하나 쓰면 모든 acquire 동작을 대신할 수 있나요?', ['아니요. 실제 의존 관계와 필요한 장벽, CPU별 규칙을 확인해야 해요', '네. if 문은 모든 미리 읽기를 자동으로 금지해요'], '정답은 첫 번째예요. 조건에 따른 진행과 뒤의 읽기 순서는 구별해야 해요. 원문도 조건 의존성 뒤의 읽기 순서를 별도로 보강하므로 임의의 분기 하나로 모든 acquire를 대체할 수 없어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_406.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
